const item = $input.first().json;
const body = item.body ?? item;
const data = body.data ?? {};
const key = data.key ?? {};
const remoteJid = String(key.remoteJid ?? '').replace(/:\d+@/, '@');
const event = String(body.event ?? '').toLowerCase();
const fromMe = key.fromMe === true;
const isGroup = remoteJid.endsWith('@g.us') || remoteJid.endsWith('@broadcast');
const owner = String($env.OWNER_NUMBER ?? '').replace(/\D/g, '');
const sender = String(remoteJid).split('@')[0].replace(/\D/g, '');
const message = data.message ?? {};
const text = message.conversation
  ?? message.extendedTextMessage?.text
  ?? message.imageMessage?.caption
  ?? message.videoMessage?.caption
  ?? '';

if (event !== 'messages.upsert') return [];
if (!remoteJid) return [];
if (fromMe || isGroup) return [];
if (!text.trim()) return [];
if (owner && sender !== owner) return [];

return [{
  json: {
    chatId: remoteJid,
    instance: body.instance ?? 'cardapio',
    text: text.trim(),
    pushName: data.pushName ?? ''
  }
}];

