const menu = $('Extrai cardápio').first().json.output ?? {};
const template = $input.first().json.template ?? '';

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const categorias = Array.isArray(menu.categorias) ? menu.categorias : [];
if (categorias.length === 0) {
  throw new Error('Não consegui identificar itens no cardápio. Envie novamente com os pratos e preços.');
}

const categoriasHtml = categorias
  .filter((categoria) => Array.isArray(categoria?.itens) && categoria.itens.length > 0)
  .map((categoria) => {
    const itens = categoria.itens.map((item) => {
      const descricao = item?.descricao
        ? `<div class="item-desc">${esc(item.descricao)}</div>`
        : '';
      return `
        <div class="item">
          <div class="item-info">
            <div class="item-nome">${esc(item?.nome)}</div>
            ${descricao}
          </div>
          <div class="item-preco">${esc(item?.preco || '—')}</div>
        </div>`;
    }).join('');

    return `
      <section class="categoria">
        <h2>${esc(categoria?.nome || 'Pratos')}</h2>
        ${itens}
      </section>`;
  })
  .join('');

if (!categoriasHtml.trim()) {
  throw new Error('Não consegui identificar itens no cardápio. Envie novamente com os pratos e preços.');
}

const data = String(menu.data ?? '').trim()
  ? esc(menu.data)
  : new Date().toLocaleDateString('pt-BR', {
      timeZone: 'America/Fortaleza',
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    });

const restaurante = esc($env.RESTAURANT_NAME || menu.estabelecimento || 'Restaurante');
const titulo = esc(menu.titulo || 'Cardápio de Hoje');
const observacoes = String(menu.observacoes ?? '').trim()
  ? `<div class="obs"><strong>Observações:</strong> ${esc(menu.observacoes)}</div>`
  : '';

const html = template
  .replaceAll('{{TITULO}}', titulo)
  .replaceAll('{{RESTAURANTE}}', restaurante)
  .replaceAll('{{DATA}}', data)
  .replaceAll('{{CATEGORIAS}}', categoriasHtml)
  .replaceAll('{{OBSERVACOES}}', observacoes);

return [{ json: { html } }];

const html = $input.first().json.html;
if (!html) throw new Error('HTML do cardápio não foi gerado.');

return [{
  json: {},
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html'
    }
  }
}];

const bin = $input.first().binary?.data;
if (!bin) throw new Error('Imagem do cardápio não foi gerada.');

const buffer = await helpers.getBinaryDataBuffer(0, 'data');
const original = $('Filtrar mensagem').first().json;
const restaurante = String($env.RESTAURANT_NAME ?? '').trim();

return [{
  json: {
    number: original.chatId,
    mediatype: 'image',
    mimetype: 'image/jpeg',
    fileName: 'cardapio.jpg',
    caption: `Cardápio de hoje${restaurante ? ' — ' + restaurante : ''} 🍽️`,
    media: buffer.toString('base64')
  }
}];
